body.raw:
{
  "type": "object",
  "properties": {
    "to": {
      "description": "Recipient",
      "type": "string"
    },
    "media_url": {
      "description": "Public HTTPS URL of the media.",
      "type": "string"
    },
    "media_type": {
      "description": "Media type",
      "type": "string",
      "enum": [
        "image",
        "video",
        "document",
        "audio"
      ]
    },
    "caption": {
      "description": "Caption",
      "type": "string"
    }
  },
  "required": [
    "to",
    "media_url"
  ]
}

{
  "type": "object",
  "properties": {
    "to": {
      "description": "Recipient",
      "type": "string"
    },
    "key": {
      "description": "The key of the message to react to.",
      "type": "object",
      "properties": {
        "remoteJid": {
          "description": "Remote JID",
          "type": "string"
        },
        "fromMe": {
          "description": "From me",
          "type": "boolean"
        },
        "id": {
          "description": "Message ID",
          "type": "string"
        }
      },
      "required": [
        "remoteJid",
        "id"
      ]
    },
    "reaction": {
      "description": "A single emoji, or empty to remove.",
      "type": "string"
    }
  },
  "required": [
    "to",
    "key",
    "reaction"
  ]
}

{
  "type": "object",
  "properties": {
    "to": {
      "description": "Recipient",
      "type": "string"
    },
    "name": {
      "description": "Question",
      "type": "string"
    },
    "selectableCount": {
      "description": "How many options a voter may pick.",
      "type": "number"
    },
    "values": {
      "description": "At least 2 option strings.",
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  },
  "required": [
    "to",
    "name",
    "selectableCount",
    "values"
  ]
}

{
  "type": "object",
  "properties": {
    "to": {
      "description": "Recipient",
      "type": "string"
    },
    "audio": {
      "description": "Public HTTPS URL of the audio (prefer .ogg/opus for PTT).",
      "type": "string"
    }
  },
  "required": [
    "to",
    "audio"
  ]
}

{
  "type": "object",
  "properties": {
    "to": {
      "description": "Recipient",
      "type": "string"
    },
    "sticker": {
      "description": "Public HTTPS URL of a .webp sticker image.",
      "type": "string"
    }
  },
  "required": [
    "to",
    "sticker"
  ]
}

{
  "type": "object",
  "properties": {
    "type": {
      "description": "Type",
      "type": "string",
      "enum": [
        "text",
        "image",
        "audio"
      ]
    },
    "content": {
      "description": "Text for text/audio, or a media URL for image.",
      "type": "string"
    },
    "caption": {
      "description": "Optional caption for image/video.",
      "type": "string"
    },
    "backgroundColor": {
      "description": "Background",
      "type": "string"
    },
    "font": {
      "description": "1=SERIF 2=NORICAN 3=BRYNDAN 4=BEBAS_NEUE.",
      "type": "number"
    },
    "allContacts": {
      "description": "true = all contacts, false = use statusJidList.",
      "type": "boolean"
    },
    "statusJidList": {
      "description": "Recipient phone numbers (when allContacts is false).",
      "type": "array",
      "items": {
        "type": "string"
      }
    }
  },
  "required": [
    "type",
    "content"
  ]
}

{
  "type": "object",
  "properties": {
    "readMessages": {
      "description": "Array of message key objects.",
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "key": {
            "description": "Key",
            "type": "object",
            "properties": {
              "remoteJid": {
                "description": "Remote JID",
                "type": "string"
              },
              "fromMe": {
                "description": "From me",
                "type": "boolean"
              },
              "id": {
                "description": "Message ID",
                "type": "string"
              }
            },
            "required": [
              "remoteJid",
              "fromMe",
              "id"
            ]
          }
        },
        "required": [
          "key"
        ]
      }
    }
  },
  "required": [
    "readMessages"
  ]
}

{
  "type": "object",
  "properties": {
    "rejectCall": {
      "description": "Reject calls",
      "type": "boolean"
    },
    "msgCall": {
      "description": "Call message",
      "type": "string"
    },
    "groupsIgnore": {
      "description": "Ignore groups",
      "type": "boolean"
    },
    "alwaysOnline": {
      "description": "Always online",
      "type": "boolean"
    },
    "readMessages": {
      "description": "Read messages",
      "type": "boolean"
    },
    "readStatus": {
      "description": "Read status",
      "type": "boolean"
    },
    "syncFullHistory": {
      "description": "Sync full history",
      "type": "boolean"
    }
  },
  "required": []
}
